        "cw": ["en": "Crash watch", "es": "Vigilancia de caídas", "fr": "Veille d'accident", "de": "Sturzwache", "pt": "Vigilância de queda", "it": "Sorveglianza incidenti", "ja": "クラッシュウォッチ", "zh": "跌倒守护", "hi": "क्रैश वॉच", "ar": "مراقبة الحوادث"],
        "cw.arm": ["en": "Arm the crash watch", "es": "Activar la vigilancia de caídas", "fr": "Armer la veille d'accident", "de": "Sturzwache scharfschalten", "pt": "Armar a vigilância de queda", "it": "Attiva la sorveglianza incidenti", "ja": "クラッシュウォッチを作動させる", "zh": "启用跌倒守护", "hi": "क्रैश वॉच सक्रिय करें", "ar": "فعّل مراقبة الحوادث"],
        "cw.disarm": ["en": "Disarm", "es": "Desactivar", "fr": "Désarmer", "de": "Entschärfen", "pt": "Desarmar", "it": "Disattiva", "ja": "解除する", "zh": "停用", "hi": "निष्क्रिय करें", "ar": "ألغِ التفعيل"],
        "cw.sub": ["en": "Off by default, programmed by you: a critical reading (a fall the watch felt, a collapsing pulse) opens “are you okay?” — unanswered attempts contact your trusted person, and emergency services only if you tick the box. Gentle drift check-ins can never trigger this.", "es": "Desactivada por defecto y configurada por ti: una lectura crítica (una caída que el reloj notó, un pulso que se desploma) abre «¿estás bien?»; si no respondes, se contacta a tu persona de confianza, y a los servicios de emergencia solo si marcas la casilla. Las comprobaciones suaves por desviación nunca pueden dispararla.", "fr": "Désactivée par défaut et programmée par vous : une mesure critique (une chute ressentie par la montre, un pouls qui s'effondre) ouvre « ça va ? » — sans réponse, votre personne de confiance est contactée, et les secours seulement si vous cochez la case. Les vérifications douces de dérive ne peuvent jamais la déclencher.", "de": "Standardmäßig aus und von dir eingestellt: Ein kritischer Messwert (ein Sturz, den die Uhr gespürt hat, ein einbrechender Puls) öffnet „Alles in Ordnung?“ — bleiben die Versuche unbeantwortet, wird deine Vertrauensperson benachrichtigt, und der Rettungsdienst nur, wenn du das Kästchen setzt. Sanfte Abweichungs-Check-ins können das nie auslösen.", "pt": "Desligada por omissão e programada por si: uma leitura crítica (uma queda que o relógio sentiu, um pulso a colapsar) abre «está bem?» — se não responder, contacta-se a sua pessoa de confiança, e os serviços de emergência só se assinalar a caixa. As verificações suaves de desvio nunca a podem disparar.", "it": "Disattivata di default e impostata da te: una misurazione critica (una caduta che l'orologio ha sentito, un polso che crolla) apre «tutto bene?» — se non rispondi viene contattata la tua persona di fiducia, e i soccorsi solo se spunti la casella. I check-in leggeri sulla deriva non possono mai farla scattare.", "ja": "既定では切ってあり、設定するのはあなたです。重大な測定値（時計が感じた転倒、急落する脈）が「大丈夫ですか？」を開き、応答がなければ信頼する人に連絡します。緊急サービスへの連絡は、あなたがチェックを入れた場合だけです。穏やかなドリフトの確認がこれを引き起こすことはありません。", "zh": "默认关闭，由你来设定：一次危急读数（手表感知到的跌倒、骤降的脉搏）会弹出「你还好吗？」— 若无人应答，会联系你的信任联系人；只有你勾选了，才会联系紧急服务。温和的偏移问候永远不会触发它。", "hi": "डिफ़ॉल्ट रूप से बंद, और इसे आप ही तय करते हैं: कोई गंभीर रीडिंग (घड़ी को महसूस हुआ गिरना, गिरती हुई नब्ज़) «क्या आप ठीक हैं?» खोलती है — उत्तर न मिलने पर आपके भरोसेमंद व्यक्ति से संपर्क होता है, और आपातकालीन सेवाओं से केवल तभी जब आपने वह विकल्प चुना हो। हल्के ड्रिफ़्ट चेक-इन इसे कभी सक्रिय नहीं कर सकते।", "ar": "مُعطَّلة افتراضيًا وأنت من يضبطها: قراءة حرجة (سقطة شعرت بها الساعة، نبض ينهار) تفتح «هل أنت بخير؟» — وإن لم تُجب جرى الاتصال بشخصك الموثوق، وبخدمات الطوارئ فقط إن أشّرت على ذلك. ولا يمكن لاطمئنانات الانحراف اللطيفة أن تُطلقها أبدًا."],
        "cw.sensitivity": ["en": "Sensitivity", "es": "Sensibilidad", "fr": "Sensibilité", "de": "Empfindlichkeit", "pt": "Sensibilidade", "it": "Sensibilità", "ja": "感度", "zh": "灵敏度", "hi": "संवेदनशीलता", "ar": "الحساسية"],
        "cw.sensitivity.sub": ["en": "Cautious escalates a rung earlier; assertive a rung later. Crisis language and critical events have floors no dial can lower.", "es": "Cauteloso sube un peldaño antes; asertivo, uno después. El lenguaje de crisis y los eventos críticos tienen mínimos que ningún control puede bajar.", "fr": "Prudent monte d'un cran plus tôt ; affirmé, d'un cran plus tard. Le langage de crise et les événements critiques ont des planchers qu'aucun réglage n'abaisse.", "de": "Vorsichtig eskaliert eine Stufe früher, bestimmt eine Stufe später. Krisensprache und kritische Ereignisse haben Untergrenzen, die kein Regler senkt.", "pt": "Cauteloso sobe um degrau mais cedo; assertivo, um mais tarde. A linguagem de crise e os eventos críticos têm mínimos que nenhum controlo baixa.", "it": "Cauto sale di un gradino prima; assertivo di uno dopo. Il linguaggio di crisi e gli eventi critici hanno soglie minime che nessuna manopola abbassa.", "ja": "「慎重」は一段早く、「積極」は一段遅く上げます。危機を示す言葉と重大な事象には、どのつまみでも下げられない下限があります。", "zh": "「谨慎」提前一级升级，「果断」推后一级。危机性言语和危急事件都有任何旋钮都无法调低的下限。", "hi": "«सतर्क» एक पायदान पहले बढ़ाता है; «दृढ़» एक पायदान बाद में। संकट की भाषा और गंभीर घटनाओं की ऐसी न्यूनतम सीमाएँ हैं जिन्हें कोई डायल नीचे नहीं कर सकता।", "ar": "«الحذر» يصعّد درجةً أبكر، و«الحازم» درجةً أمتأخر. ولغة الأزمة والأحداث الحرجة لها حدود دنيا لا يخفضها أي مؤشر."],
        "cw.trusted": ["en": "Trusted person", "es": "Persona de confianza", "fr": "Personne de confiance", "de": "Vertrauensperson", "pt": "Pessoa de confiança", "it": "Persona di fiducia", "ja": "信頼する人", "zh": "信任的人", "hi": "भरोसेमंद व्यक्ति", "ar": "الشخص الموثوق"],
        "cw.reach": ["en": "How to reach them (email or phone)", "es": "Cómo contactarla (correo o teléfono)", "fr": "Comment la joindre (e-mail ou téléphone)", "de": "Wie sie erreichbar ist (E-Mail oder Telefon)", "pt": "Como contactá-la (email ou telefone)", "it": "Come raggiungerla (email o telefono)", "ja": "連絡方法（メールまたは電話）", "zh": "如何联系他们（邮箱或电话）", "hi": "उन तक कैसे पहुँचें (ईमेल या फ़ोन)", "ar": "كيفية الوصول إليه (بريد أو هاتف)"],
        "res.waiver": ["en": "Autonomous-resuscitation waiver", "es": "Consentimiento de reanimación autónoma", "fr": "Renonciation pour réanimation autonome", "de": "Verzichtserklärung für autonome Wiederbelebung", "pt": "Consentimento de reanimação autónoma", "it": "Liberatoria per rianimazione autonoma", "ja": "自律的蘇生に関する同意書", "zh": "自主复苏授权书", "hi": "स्वायत्त पुनर्जीवन अनुमति-पत्र", "ar": "تنازل الإنعاش الذاتي"],
        "res.waiver.sub": ["en": "Unlock automatic operation: CPR that starts on detection, and a fully-automatic AED that shocks on its own analysis after the robot verifies everyone is clear. Until signed, every start needs an on-scene confirmation and no shock is ever delivered.", "es": "Habilita el funcionamiento automático: RCP que empieza al detectarse, y un DEA totalmente automático que descarga según su propio análisis después de que el robot verifique que nadie toca a la persona. Hasta que se firme, cada inicio necesita una confirmación en el lugar y no se administra ninguna descarga.", "fr": "Débloque le fonctionnement automatique : une RCP qui démarre à la détection, et un DAE entièrement automatique qui délivre le choc selon sa propre analyse une fois que le robot a vérifié que personne ne touche la victime. Tant que ce n'est pas signé, chaque démarrage exige une confirmation sur place et aucun choc n'est jamais délivré.", "de": "Schaltet den automatischen Betrieb frei: eine Reanimation, die bei Erkennung beginnt, und ein vollautomatischer AED, der nach eigener Analyse schockt, sobald der Roboter geprüft hat, dass niemand die Person berührt. Bis zur Unterschrift braucht jeder Start eine Bestätigung vor Ort, und es wird nie ein Schock abgegeben.", "pt": "Desbloqueia o funcionamento automático: RCP que começa ao detetar, e um DAE totalmente automático que choca segundo a sua própria análise depois de o robô verificar que ninguém está em contacto. Até ser assinado, cada início precisa de uma confirmação no local e nunca é administrado qualquer choque.", "it": "Sblocca il funzionamento automatico: una RCP che parte al rilevamento e un DAE completamente automatico che eroga la scarica in base alla propria analisi dopo che il robot ha verificato che nessuno tocchi la persona. Finché non è firmata, ogni avvio richiede una conferma sul posto e non viene mai erogata alcuna scarica.", "ja": "自動での作動を解除します。検知した時点で始まる心肺蘇生と、ロボットが周囲の安全を確認したうえで自身の解析にもとづいて通電する全自動 AED です。署名するまでは、開始のたびに現場での確認が必要で、通電は一切行われません。", "zh": "解锁自动运行：检测到即开始的心肺复苏，以及在机器人确认所有人都已离开后、依自身分析放电的全自动 AED。在签署之前，每次启动都需要现场确认，并且绝不会放电。", "hi": "स्वचालित संचालन खोलता है: पता चलते ही शुरू होने वाला सीपीआर, और एक पूर्ण-स्वचालित AED जो रोबोट द्वारा यह जाँच लेने के बाद कि सब दूर हैं, अपने ही विश्लेषण पर झटका देता है। हस्ताक्षर होने तक हर शुरुआत के लिए मौक़े पर पुष्टि चाहिए और कोई झटका कभी नहीं दिया जाता।", "ar": "يفتح التشغيل التلقائي: إنعاش قلبي رئوي يبدأ عند الاكتشاف، ومزيل رجفان آلي بالكامل يصعق بناءً على تحليله الخاص بعد أن يتحقق الآلي من ابتعاد الجميع. وإلى أن يُوقَّع، تحتاج كل بداية إلى تأكيد في الموقع ولا تُعطى أي صدمة إطلاقًا."],
        "res.name": ["en": "Your name", "es": "Tu nombre", "fr": "Votre nom", "de": "Dein Name", "pt": "O seu nome", "it": "Il tuo nome", "ja": "お名前", "zh": "你的姓名", "hi": "आपका नाम", "ar": "اسمك"],
        "res.sign.ph": ["en": "Type your legal name to sign", "es": "Escribe tu nombre legal para firmar", "fr": "Saisissez votre nom légal pour signer", "de": "Zum Unterschreiben deinen amtlichen Namen eintippen", "pt": "Escreva o seu nome legal para assinar", "it": "Digita il tuo nome legale per firmare", "ja": "署名するには、法律上の氏名を入力してください", "zh": "输入你的法定姓名以签署", "hi": "हस्ताक्षर के लिए अपना क़ानूनी नाम लिखें", "ar": "اكتب اسمك القانوني للتوقيع"],
        "res.sign": ["en": "Sign & submit waiver", "es": "Firmar y enviar el consentimiento", "fr": "Signer et envoyer la renonciation", "de": "Verzichtserklärung unterschreiben und senden", "pt": "Assinar e enviar o consentimento", "it": "Firma e invia la liberatoria", "ja": "署名して同意書を提出", "zh": "签署并提交授权书", "hi": "हस्ताक्षर करें और अनुमति-पत्र भेजें", "ar": "وقّع وأرسل التنازل"],
        "res.signed": ["en": "SIGNED", "es": "FIRMADO", "fr": "SIGNÉ", "de": "UNTERSCHRIEBEN", "pt": "ASSINADO", "it": "FIRMATA", "ja": "署名済み", "zh": "已签署", "hi": "हस्ताक्षरित", "ar": "موقَّع"],
        "res.revoke": ["en": "Revoke — restore confirm-gated operation", "es": "Revocar: volver al funcionamiento con confirmación", "fr": "Révoquer — rétablir le fonctionnement sous confirmation", "de": "Widerrufen — Betrieb wieder nur mit Bestätigung", "pt": "Revogar — repor o funcionamento com confirmação", "it": "Revoca — ripristina il funzionamento con conferma", "ja": "取り消す — 確認を必須とする動作に戻す", "zh": "撤回 — 恢复为需确认才能操作", "hi": "वापस लें — पुष्टि-आधारित संचालन बहाल करें", "ar": "أبطِل — أعِد التشغيل المشروط بالتأكيد"],
        "mid": ["en": "Medical ID", "es": "Identificación médica", "fr": "Fiche médicale", "de": "Notfallpass", "pt": "Identificação médica", "it": "Scheda medica", "ja": "メディカル ID", "zh": "医疗卡", "hi": "मेडिकल आईडी", "ar": "البطاقة الطبية"],
        "mid.issue": ["en": "Issue Medical ID", "es": "Emitir la identificación médica", "fr": "Émettre la fiche médicale", "de": "Notfallpass ausstellen", "pt": "Emitir a identificação médica", "it": "Emetti la scheda medica", "ja": "メディカル ID を発行", "zh": "签发医疗卡", "hi": "मेडिकल आईडी जारी करें", "ar": "أصدر البطاقة الطبية"],
        "mid.sub": ["en": "A shareable card for first responders: condition-level facts only, readable from a locked phone. Re-issuing rotates the QR and kills the old one.", "es": "Una tarjeta compartible para el personal de emergencias: solo datos de nivel clínico, legible desde un teléfono bloqueado. Volver a emitirla rota el QR y anula el anterior.", "fr": "Une fiche partageable pour les secouristes : uniquement des faits de niveau clinique, lisible depuis un téléphone verrouillé. La réémettre fait tourner le QR et annule l'ancien.", "de": "Eine teilbare Karte für Ersthelfer: nur Angaben auf Befundebene, vom gesperrten Telefon lesbar. Ein erneutes Ausstellen wechselt den QR-Code und macht den alten ungültig.", "pt": "Um cartão partilhável para os primeiros socorros: apenas factos de nível clínico, legível a partir de um telefone bloqueado. Reemitir roda o QR e anula o anterior.", "it": "Una scheda condivisibile per i soccorritori: solo dati di livello clinico, leggibile da un telefono bloccato. Riemetterla ruota il QR e annulla il precedente.", "ja": "救急対応者に渡せるカードです。記載は病態レベルの事実のみで、ロックされた端末からでも読めます。再発行すると QR が更新され、古いものは無効になります。", "zh": "一张可交给急救人员的卡片：只含病情层面的事实，锁屏状态下也能读取。重新签发会更换二维码并作废旧的。", "hi": "प्राथमिक उत्तरदाताओं के लिए साझा किया जा सकने वाला कार्ड: केवल स्थिति-स्तर के तथ्य, लॉक फ़ोन से भी पढ़ने योग्य। दोबारा जारी करने पर QR बदल जाता है और पुराना रद्द हो जाता है।", "ar": "بطاقة يمكن مشاركتها مع المسعفين: حقائق على مستوى الحالة فقط، وتُقرأ من هاتف مقفل. وإعادة الإصدار تُبدّل رمز الاستجابة وتُبطل القديم."],
        "mid.rotate": ["en": "Rotate QR", "es": "Rotar el QR", "fr": "Renouveler le QR", "de": "QR wechseln", "pt": "Rodar o QR", "it": "Ruota il QR", "ja": "QR を更新", "zh": "更换二维码", "hi": "QR बदलें", "ar": "بدّل رمز الاستجابة"],
        "mid.revoke": ["en": "Revoke card", "es": "Revocar la tarjeta", "fr": "Révoquer la fiche", "de": "Karte widerrufen", "pt": "Revogar o cartão", "it": "Revoca la scheda", "ja": "カードを失効させる", "zh": "吊销卡片", "hi": "कार्ड रद्द करें", "ar": "أبطِل البطاقة"],
        "mid.issued": ["en": "Card issued", "es": "Tarjeta emitida", "fr": "Fiche émise", "de": "Karte ausgestellt", "pt": "Cartão emitido", "it": "Scheda emessa", "ja": "カードを発行しました", "zh": "卡片已签发", "hi": "कार्ड जारी हुआ", "ar": "صدرت البطاقة"],
        "mid.responder": ["en": "What a responder sees", "es": "Lo que ve el personal de emergencias", "fr": "Ce que voit un secouriste", "de": "Was ein Ersthelfer sieht", "pt": "O que vê quem socorre", "it": "Cosa vede un soccorritore", "ja": "救急対応者に見えるもの", "zh": "急救人员看到的内容", "hi": "उत्तरदाता को क्या दिखता है", "ar": "ما يراه المسعف"],
        "mid.print": ["en": "Print or lock-screen the QR at:", "es": "Imprime el QR o ponlo en la pantalla de bloqueo en:", "fr": "Imprimez le QR ou mettez-le en écran verrouillé à :", "de": "Den QR-Code ausdrucken oder auf den Sperrbildschirm legen unter:", "pt": "Imprima o QR ou coloque-o no ecrã de bloqueio em:", "it": "Stampa il QR o mettilo nella schermata di blocco su:", "ja": "QR を印刷するか、ロック画面に設定してください：", "zh": "在此打印二维码或将其设为锁屏：", "hi": "QR यहाँ से प्रिंट करें या लॉक-स्क्रीन पर लगाएँ:", "ar": "اطبع رمز الاستجابة أو ضعه على شاشة القفل من:"],
        "fa.coach": ["en": "Coach CPR", "es": "Guiar la RCP", "fr": "Guider la RCP", "de": "Reanimation anleiten", "pt": "Orientar a RCP", "it": "Guida la RCP", "ja": "心肺蘇生を指導", "zh": "指导心肺复苏", "hi": "सीपीआर में मार्गदर्शन", "ar": "أرشِد إلى الإنعاش"],
        "fa.confirm": ["en": "Confirm: unresponsive, not breathing — start compressions", "es": "Confirma: no responde, no respira; empieza las compresiones", "fr": "Confirmez : ne réagit pas, ne respire pas — commencez les compressions", "de": "Bestätige: reagiert nicht, atmet nicht — mit den Kompressionen beginnen", "pt": "Confirme: não responde, não respira — comece as compressões", "it": "Conferma: non risponde, non respira — inizia le compressioni", "ja": "確認：反応なし・呼吸なし — 胸骨圧迫を開始してください", "zh": "确认：无反应、无呼吸 — 开始按压", "hi": "पुष्टि करें: कोई प्रतिक्रिया नहीं, साँस नहीं — छाती दबाना शुरू करें", "ar": "أكّد: لا يستجيب ولا يتنفس — ابدأ الضغطات"],
        "fa.start": ["en": "Start CPR (pre-authorized)", "es": "Iniciar la RCP (autorizada de antemano)", "fr": "Démarrer la RCP (préautorisée)", "de": "Reanimation starten (vorab genehmigt)", "pt": "Iniciar a RCP (pré-autorizada)", "it": "Avvia la RCP (preautorizzata)", "ja": "心肺蘇生を開始（事前承認済み）", "zh": "开始心肺复苏（已预先授权）", "hi": "सीपीआर शुरू करें (पूर्व-अनुमत)", "ar": "ابدأ الإنعاش (مأذون مسبقًا)"],
        "fa.stop": ["en": "Stop CPR", "es": "Detener la RCP", "fr": "Arrêter la RCP", "de": "Reanimation stoppen", "pt": "Parar a RCP", "it": "Ferma la RCP", "ja": "心肺蘇生を止める", "zh": "停止心肺复苏", "hi": "सीपीआर रोकें", "ar": "أوقف الإنعاش"],
        "fa.perform": ["en": "Perform CPR…", "es": "Realizar la RCP…", "fr": "Effectuer la RCP…", "de": "Reanimation durchführen …", "pt": "Realizar a RCP…", "it": "Esegui la RCP…", "ja": "心肺蘇生を実施…", "zh": "执行心肺复苏…", "hi": "सीपीआर करें…", "ar": "نفّذ الإنعاش…"],
        "fa.aed": ["en": "Fetch AED", "es": "Traer el DEA", "fr": "Aller chercher le DAE", "de": "AED holen", "pt": "Ir buscar o DAE", "it": "Porta il DAE", "ja": "AED を取ってくる", "zh": "取来 AED", "hi": "AED लाएँ", "ar": "أحضِر مزيل الرجفان"],
        "fa.ems": ["en": "Meet EMS", "es": "Recibir a los servicios de emergencia", "fr": "Accueillir les secours", "de": "Rettungsdienst einweisen", "pt": "Receber os serviços de emergência", "it": "Accogli i soccorsi", "ja": "救急隊を出迎える", "zh": "接应急救人员", "hi": "आपात सेवा दल को लेने जाएँ", "ar": "استقبِل فريق الإسعاف"],
        "rob.bind": ["en": "Bind a robot", "es": "Vincular un robot", "fr": "Lier un robot", "de": "Einen Roboter binden", "pt": "Vincular um robô", "it": "Collega un robot", "ja": "ロボットを結び付ける", "zh": "绑定一个机器人", "hi": "एक रोबोट जोड़ें", "ar": "اربط آليًا"],
        "rob.bind.go": ["en": "Bind", "es": "Vincular", "fr": "Lier", "de": "Binden", "pt": "Vincular", "it": "Collega", "ja": "結び付ける", "zh": "绑定", "hi": "जोड़ें", "ar": "اربط"],
        "rob.sub": ["en": "Bound robots respond to escalations: mobile bodies come to you; vacuums dock and clear the floor.", "es": "Los robots vinculados responden a las escaladas: los cuerpos móviles acuden a ti; las aspiradoras se acoplan y despejan el suelo.", "fr": "Les robots liés répondent aux escalades : les corps mobiles viennent à vous ; les aspirateurs se remettent en base et dégagent le sol.", "de": "Gebundene Roboter reagieren auf Eskalationen: mobile Körper kommen zu dir, Sauger docken an und räumen den Boden frei.", "pt": "Os robôs vinculados respondem às escaladas: os corpos móveis vão ter consigo; os aspiradores acoplam e libertam o chão.", "it": "I robot collegati rispondono alle escalation: i corpi mobili vengono da te; gli aspirapolvere tornano alla base e liberano il pavimento.", "ja": "結び付けたロボットは段階上昇に応じます。動く身体はあなたのもとへ向かい、掃除機はドックに戻って床を空けます。", "zh": "已绑定的机器人会响应升级：可移动的躯体会赶到你身边，扫地机则回座并清空地面。", "hi": "जुड़े हुए रोबोट एस्केलेशन पर प्रतिक्रिया देते हैं: चलने वाले शरीर आपके पास आते हैं; वैक्यूम डॉक पर लौटकर फ़र्श ख़ाली कर देते हैं।", "ar": "الآليّات المرتبطة تستجيب للتصعيد: الأجسام المتحركة تأتي إليك، والمكانس تعود إلى قواعدها وتُخلي الأرض."],
        "rob.coordinated": ["en": "Coordinated response", "es": "Respuesta coordinada", "fr": "Réponse coordonnée", "de": "Abgestimmte Reaktion", "pt": "Resposta coordenada", "it": "Risposta coordinata", "ja": "連携した対応", "zh": "协同响应", "hi": "समन्वित प्रतिक्रिया", "ar": "استجابة منسّقة"],
        "rob.severity": ["en": "How each severity resolves", "es": "Cómo se resuelve cada nivel de gravedad", "fr": "Comment chaque niveau de gravité se règle", "de": "Wie sich jede Schwerestufe auflöst", "pt": "Como se resolve cada nível de gravidade", "it": "Come si risolve ogni livello di gravità", "ja": "重症度ごとの収め方", "zh": "各严重级别如何处置", "hi": "हर गंभीरता स्तर कैसे निपटता है", "ar": "كيف تُحسم كل درجة خطورة"],
        "rob.onesc": ["en": "On escalation: {directive}", "es": "Al escalar: {directive}", "fr": "En cas d'escalade : {directive}", "de": "Bei Eskalation: {directive}", "pt": "Ao escalar: {directive}", "it": "In caso di escalation: {directive}", "ja": "段階が上がったとき：{directive}", "zh": "升级时：{directive}", "hi": "एस्केलेशन पर: {directive}", "ar": "عند التصعيد: {directive}"],
        "mon": ["en": "Live Monitoring", "es": "Vigilancia en directo", "fr": "Surveillance en direct", "de": "Live-Überwachung", "pt": "Vigilância em direto", "it": "Monitoraggio dal vivo", "ja": "ライブ・モニタリング", "zh": "实时监测", "hi": "लाइव निगरानी", "ar": "المراقبة الحيّة"],
        "mon.sub": ["en": "Send a sample. The Guardian compares it to your baseline.", "es": "Envía una muestra. El Guardián la compara con tu línea base.", "fr": "Envoyez un échantillon. Le Gardien le compare à votre référence.", "de": "Schick eine Probe. Der Guardian vergleicht sie mit deiner Grundlinie.", "pt": "Envie uma amostra. O Guardião compara-a com a sua linha de base.", "it": "Invia un campione. Il Guardiano lo confronta con la tua linea di base.", "ja": "サンプルを送ってください。ガーディアンがあなたの基準値と比べます。", "zh": "发送一份样本。守护者会将它与你的基线比较。", "hi": "एक नमूना भेजें। गार्जियन उसकी तुलना आपकी आधार-रेखा से करेगा।", "ar": "أرسِل عيّنة، فيقارنها الحارس بخطّ أساسك."],
        "mon.send": ["en": "Send sample", "es": "Enviar la muestra", "fr": "Envoyer l'échantillon", "de": "Probe senden", "pt": "Enviar a amostra", "it": "Invia il campione", "ja": "サンプルを送る", "zh": "发送样本", "hi": "नमूना भेजें", "ar": "أرسِل العيّنة"],
        "mon.person": ["en": "Bringing in a person", "es": "Trayendo a una persona", "fr": "On fait venir une personne", "de": "Eine Person wird hinzugezogen", "pt": "A trazer uma pessoa", "it": "Sto coinvolgendo una persona", "ja": "人に入ってもらっています", "zh": "正在请一位真人介入", "hi": "किसी व्यक्ति को बुलाया जा रहा है", "ar": "جارٍ إشراك شخص"],
        "mon.resumes": ["en": "Monitoring resumes", "es": "La vigilancia se reanuda", "fr": "La surveillance reprend", "de": "Die Überwachung läuft weiter", "pt": "A vigilância recomeça", "it": "Il monitoraggio riprende", "ja": "モニタリングを再開します", "zh": "监测已恢复", "hi": "निगरानी फिर शुरू", "ar": "تستأنف المراقبة"],
        "mon.about": ["en": "About the guidance for {condition}.", "es": "Sobre las indicaciones para {condition}.", "fr": "À propos des conseils pour {condition}.", "de": "Zu den Hinweisen für {condition}.", "pt": "Sobre as orientações para {condition}.", "it": "Sulle indicazioni per {condition}.", "ja": "{condition} についての案内です。", "zh": "关于 {condition} 的指导。", "hi": "{condition} के लिए दिए गए मार्गदर्शन के बारे में।", "ar": "بخصوص الإرشاد المتعلق بـ {condition}."],
        "mon.add": ["en": "Anything you want to add (optional)", "es": "Algo que quieras añadir (opcional)", "fr": "Quelque chose à ajouter (facultatif)", "de": "Möchtest du etwas ergänzen? (optional)", "pt": "Algo que queira acrescentar (opcional)", "it": "Qualcosa da aggiungere (facoltativo)", "ja": "付け加えたいことがあれば（任意）", "zh": "还有什么要补充的吗（可选）", "hi": "कुछ जोड़ना चाहें तो (वैकल्पिक)", "ar": "أي شيء تودّ إضافته (اختياري)"],
        "hld.end": ["en": "End it", "es": "Terminar con todo", "fr": "Y mettre fin", "de": "Beenden", "pt": "Acabar com tudo", "it": "Metterci fine", "ja": "すべて終わらせる", "zh": "结束这一切", "hi": "इसे समाप्त करें", "ar": "أنهِ كل شيء"],
        "hld.end.pitch": ["en": "Erases everything held about you on this deployment. There is no undo, which is the point of it. Type erase to arm the button.", "es": "Borra todo lo que se guarda sobre ti en este despliegue. No hay deshacer, y ese es justamente el punto. Escribe erase para armar el botón.", "fr": "Efface tout ce qui est détenu sur vous sur ce déploiement. Il n'y a pas d'annulation, et c'est justement le but. Tapez erase pour armer le bouton.", "de": "Löscht alles, was auf diesem Deployment über Sie gehalten wird. Es gibt kein Rückgängig, und genau darum geht es. Tippen Sie erase, um den Knopf scharf zu stellen.", "pt": "Apaga tudo o que é guardado sobre si neste deployment. Não há como desfazer, e é essa a intenção. Escreva erase para armar o botão.", "it": "Cancella tutto ciò che è custodito su di te in questo deployment. Non c'è annullamento, ed è proprio il punto. Digita erase per armare il pulsante.", "ja": "この配備であなたについて保持されているすべてを消去します。取り消しはできません — それがこの機能の意味です。ボタンを有効にするには erase と入力してください。", "zh": "抹除本部署上关于你的一切。没有撤销，这正是它的意义所在。输入 erase 以启用该按钮。", "hi": "इस डिप्लॉयमेंट पर आपके बारे में रखा सब कुछ मिटा देता है। कोई पूर्ववत नहीं, और यही इसका मक़सद है। बटन सक्रिय करने के लिए erase टाइप करें।", "ar": "يمحو كل ما هو محفوظ عنك على هذا النشر. لا تراجع، وهذا هو المقصود. اكتب erase لتفعيل الزر."],
        "hld.end.ph": ["en": "erase", "es": "erase", "fr": "erase", "de": "erase", "pt": "erase", "it": "erase", "ja": "erase", "zh": "erase", "hi": "erase", "ar": "erase"],
        "hld.end.go": ["en": "Erase everything", "es": "Borrarlo todo", "fr": "Tout effacer", "de": "Alles löschen", "pt": "Apagar tudo", "it": "Cancella tutto", "ja": "すべて消去", "zh": "抹除一切", "hi": "सब कुछ मिटाएँ", "ar": "امحُ كل شيء"],
        "hld.end.gone": ["en": "Erased. This deployment holds nothing about you.", "es": "Borrado. Esta instalación no guarda nada sobre ti.", "fr": "Effacé. Ce déploiement ne détient plus rien sur vous.", "de": "Gelöscht. Diese Installation hält nichts mehr über Sie.", "pt": "Apagado. Esta instalação já não guarda nada sobre si.", "it": "Cancellato. Questa installazione non conserva più nulla su di te.", "ja": "消去しました。この導入はあなたについて何も保持していません。", "zh": "已抹除。本部署不再持有你的任何内容。", "hi": "मिटा दिया गया। यह परिनियोजन आपके बारे में कुछ नहीं रखता।", "ar": "تم المحو. لم يعد هذا النشر يحتفظ بأي شيء عنك."],
        "hld.take": ["en": "Take it with you", "es": "Llévatelo", "fr": "Emportez-le", "de": "Nimm es mit", "pt": "Leve-o consigo", "it": "Portalo con te", "ja": "持ち出す", "zh": "带走它", "hi": "इसे अपने साथ ले जाएँ", "ar": "خذه معك"],
        "hld.take.pitch": ["en": "Everything this deployment holds about you, as one file. Live credentials are left out — the rest is yours.", "es": "Todo lo que esta instalación tiene sobre ti, en un archivo. Las credenciales activas quedan fuera; el resto es tuyo.", "fr": "Tout ce que ce déploiement détient sur vous, en un fichier. Les identifiants actifs sont exclus ; le reste est à vous.", "de": "Alles, was diese Installation über Sie hat, als eine Datei. Aktive Zugangsdaten bleiben draußen — der Rest gehört Ihnen.", "pt": "Tudo o que esta instalação tem sobre si, num ficheiro. As credenciais activas ficam de fora; o resto é seu.", "it": "Tutto ciò che questa installazione ha su di te, in un file. Le credenziali attive restano fuori; il resto è tuo.", "ja": "この導入があなたについて保持しているすべてを一つのファイルに。有効な資格情報は含みません。", "zh": "本部署持有的关于您的全部内容，汇成一个文件。不含有效凭据，其余都是您的。", "hi": "यह परिनियोजन आपके बारे में जो कुछ रखता है, एक फ़ाइल में। सक्रिय क्रेडेंशियल शामिल नहीं।", "ar": "كل ما يحتفظ به هذا النشر عنك، في ملف واحد. لا تُدرج بيانات الاعتماد الفعّالة."],
        "hld.take.go": ["en": "What do you hold about me", "es": "¿Qué guardan sobre mí?", "fr": "Que détenez-vous sur moi", "de": "Was haltet ihr über mich", "pt": "O que guardam sobre mim", "it": "Cosa conservate su di me", "ja": "私について何を保持していますか", "zh": "你们持有我的哪些内容", "hi": "आप मेरे बारे में क्या रखते हैं", "ar": "ماذا تحتفظون به عني"],
        "hld.take.held": ["en": "{t} table(s), {r} row(s)", "es": "{t} tabla(s), {r} fila(s)", "fr": "{t} table(s), {r} ligne(s)", "de": "{t} Tabelle(n), {r} Zeile(n)", "pt": "{t} tabela(s), {r} linha(s)", "it": "{t} tabella/e, {r} riga/he", "ja": "{t} 個のテーブル、{r} 行", "zh": "{t} 张表，{r} 行", "hi": "{t} तालिका, {r} पंक्तियाँ", "ar": "{t} جدول، {r} صف"],
        "cust": ["en": "Vault custody", "es": "Custodia de la bóveda", "fr": "Garde du coffre", "de": "Tresor-Verwahrung", "pt": "Custódia do cofre", "it": "Custodia della cassaforte", "ja": "保管庫の管理記録", "zh": "保险库保管", "hi": "वॉल्ट अभिरक्षा", "ar": "حفظ الخزنة"],
        "cust.sub": ["en": "Chats with tandem specialists are sealed into the PDI vault — encrypted, attributed, and hash-chained. This is your copy of the proof.", "es": "Las conversaciones con especialistas en tándem se sellan en la bóveda PDI: cifradas, atribuidas y encadenadas por hash. Esta es tu copia de la prueba.", "fr": "Les échanges avec les spécialistes en tandem sont scellés dans le coffre PDI — chiffrés, attribués et chaînés par empreinte. Voici votre copie de la preuve.", "de": "Gespräche mit Tandem-Fachleuten werden im PDI-Tresor versiegelt — verschlüsselt, zugeordnet und hash-verkettet. Dies ist deine Kopie des Nachweises.", "pt": "As conversas com especialistas em tandem são seladas no cofre PDI — cifradas, atribuídas e encadeadas por hash. Esta é a sua cópia da prova.", "it": "Le conversazioni con gli specialisti in tandem sono sigillate nella cassaforte PDI — cifrate, attribuite e concatenate con hash. Questa è la tua copia della prova.", "ja": "タンデムの専門家とのやり取りは PDI 保管庫に封印されます — 暗号化され、帰属が記録され、ハッシュで連結されます。これはその証跡のあなたの控えです。", "zh": "与协同专家的对话会被封存进 PDI 保险库 — 加密、标明归属、以哈希相连。这是你留存的凭证副本。", "hi": "टैंडेम विशेषज्ञों के साथ हुई बातचीत PDI वॉल्ट में सील की जाती है — एन्क्रिप्टेड, श्रेय-सहित और हैश-श्रृंखलाबद्ध। यह उस प्रमाण की आपकी प्रति है।", "ar": "تُختم المحادثات مع الأخصائيين المرافقين في خزنة PDI — مشفّرة ومنسوبة ومتسلسلة بالتجزئة. وهذه نسختك من الإثبات."],
        "cust.none": ["en": "No sealed exchanges yet — they appear after a tandem specialist chat.", "es": "Aún no hay intercambios sellados: aparecen tras una conversación con un especialista en tándem.", "fr": "Aucun échange scellé pour l'instant — ils apparaissent après une conversation avec un spécialiste en tandem.", "de": "Noch keine versiegelten Austausche — sie erscheinen nach einem Gespräch mit einer Tandem-Fachkraft.", "pt": "Ainda sem trocas seladas — aparecem depois de uma conversa com um especialista em tandem.", "it": "Ancora nessuno scambio sigillato — compaiono dopo una conversazione con uno specialista in tandem.", "ja": "封印されたやり取りはまだありません。タンデムの専門家と話したあとに現れます。", "zh": "尚无封存的往来 — 它们会在与协同专家对话后出现。", "hi": "अभी कोई सील किया गया आदान-प्रदान नहीं — ये टैंडेम विशेषज्ञ से बातचीत के बाद दिखेंगे।", "ar": "لا مبادلات مختومة بعد — تظهر بعد محادثة مع أخصائي مرافق."],
        "cust.sealed": ["en": "{n} sealed", "es": "{n} sellados", "fr": "{n} scellés", "de": "{n} versiegelt", "pt": "{n} selados", "it": "{n} sigillati", "ja": "封印済み {n} 件", "zh": "已封存 {n} 项", "hi": "{n} सील किए गए", "ar": "{n} مختومة"],
        "cust.events": ["en": "Audit events: {n}", "es": "Eventos de auditoría: {n}", "fr": "Événements d'audit : {n}", "de": "Prüfereignisse: {n}", "pt": "Eventos de auditoria: {n}", "it": "Eventi di audit: {n}", "ja": "監査イベント：{n}", "zh": "审计事件：{n}", "hi": "ऑडिट घटनाएँ: {n}", "ar": "أحداث التدقيق: {n}"],
        "cust.chain.ok": ["en": "🔗 Audit chain intact", "es": "🔗 Cadena de auditoría intacta", "fr": "🔗 Chaîne d'audit intacte", "de": "🔗 Prüfkette unversehrt", "pt": "🔗 Cadeia de auditoria intacta", "it": "🔗 Catena di audit intatta", "ja": "🔗 監査チェーンは無傷です", "zh": "🔗 审计链完整", "hi": "🔗 ऑडिट श्रृंखला अक्षुण्ण", "ar": "🔗 سلسلة التدقيق سليمة"],
        "cust.chain.unknown": ["en": "⚠️ Audit chain status unknown", "es": "⚠️ Estado de la cadena de auditoría desconocido", "fr": "⚠️ État de la chaîne d'audit inconnu", "de": "⚠️ Zustand der Prüfkette unbekannt", "pt": "⚠️ Estado da cadeia de auditoria desconhecido", "it": "⚠️ Stato della catena di audit sconosciuto", "ja": "⚠️ 監査チェーンの状態は不明です", "zh": "⚠️ 审计链状态未知", "hi": "⚠️ ऑडिट श्रृंखला की स्थिति अज्ञात", "ar": "⚠️ حالة سلسلة التدقيق غير معروفة"],
        "cust.hash.ok": ["en": "Hash chain: intact", "es": "Cadena de hash: intacta", "fr": "Chaîne d'empreintes : intacte", "de": "Hash-Kette: unversehrt", "pt": "Cadeia de hash: intacta", "it": "Catena di hash: intatta", "ja": "ハッシュ連鎖：無傷", "zh": "哈希链：完整", "hi": "हैश श्रृंखला: अक्षुण्ण", "ar": "سلسلة التجزئة: سليمة"],
        "cust.hash.unknown": ["en": "Hash chain: unknown", "es": "Cadena de hash: desconocida", "fr": "Chaîne d'empreintes : inconnue", "de": "Hash-Kette: unbekannt", "pt": "Cadeia de hash: desconhecida", "it": "Catena di hash: sconosciuta", "ja": "ハッシュ連鎖：不明", "zh": "哈希链：未知", "hi": "हैश श्रृंखला: अज्ञात", "ar": "سلسلة التجزئة: غير معروفة"],
        "cust.origin": ["en": "Origin: {origin}", "es": "Origen: {origin}", "fr": "Origine : {origin}", "de": "Herkunft: {origin}", "pt": "Origem: {origin}", "it": "Origine: {origin}", "ja": "由来：{origin}", "zh": "来源：{origin}", "hi": "उद्गम: {origin}", "ar": "المصدر: {origin}"],
        "cust.seal": ["en": "Seal: {cipher}", "es": "Sello: {cipher}", "fr": "Sceau : {cipher}", "de": "Siegel: {cipher}", "pt": "Selo: {cipher}", "it": "Sigillo: {cipher}", "ja": "封印：{cipher}", "zh": "封印：{cipher}", "hi": "मुहर: {cipher}", "ar": "الختم: {cipher}"],
        "action.update": ["en": "Update", "es": "Actualizar", "fr": "Mettre à jour", "de": "Aktualisieren", "pt": "Atualizar", "it": "Aggiorna", "ja": "更新する", "zh": "更新", "hi": "अपडेट करें", "ar": "حدّث"],
